CREATE TRIGGER `D085_trigger_apos_inclusao` AFTER INSERT ON `D085` FOR EACH ROW BEGIN
	UPDATE D024 SET D024_D085_Id = NEW.D085_Id WHERE D024_Id=NEW.D085_D024_Id;
    #UPDATE D024 SET D024_Flag_Comercial = 'A', D024_C007_Vendedor_Interno=NEW.D085_C007_Id, D024_Classe='', D024_D021_Id=NEW.D085_D021_Id, D024_Data_Ativo=CURDATE() WHERE D024_Id=NEW.D085_D024_Id AND D024_Flag_Comercial='I';
    CALL D024_Ativar_Cliente(NEW.D085_T003_Id, NEW.D085_T005_Id, NEW.D085_T007_Id, NEW.D085_D024_Id, NEW.D085_C007_Id, NEW.D085_D021_Id, 0);
END;